<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {Refresh} from '@element-plus/icons-vue'
import request from '@/utils/request'
import {sanitizeHTML,reviewPlainText} from '@/utils/sanitize'
const actor=JSON.parse(sessionStorage.getItem('account')||'{}'),merchant=actor.role==='ROLE_UNIT'
const rows=ref([]),reviews=ref([]),finance=ref(null),tab=ref('afterSales'),busy=ref(false),detailOpen=ref(false),selectedId=ref(''),reason=ref(''),replyOpen=ref(false),replyTarget=ref(null),replyText=ref(''),persona=ref(sessionStorage.getItem('platformDemoPersona')||'701')
const selected=computed(()=>rows.value.find(r=>r.id===selectedId.value))
const money=value=>(Number(value||0)/100).toFixed(2)
const date=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'
function status(row){if(row.kind==='ordinary')return ({REQUESTED:'待商家处理',ACCEPTED:'商家已同意 · 退款渠道未接',REJECTED:'商家拒绝'})[row.status]||row.status;if(row.status==='REQUESTED')return row.merchantDecision==='PENDING'?'待商家反馈':'待独立复核';return ({PROCESSING:'待模拟现金退回',SUCCEEDED:'处理完成',REJECTED:'未通过复核',FAILED:'明确退回失败',EXCEPTION:'退回异常'})[row.status]||row.status}
const availablePrincipal=computed(()=>finance.value?.receivables.find(r=>r.orderId===selected.value?.creditOrderId)?.outstandingMinor||0)
const previewReduction=computed(()=>Math.min(selected.value?.requestedMinor||0,availablePrincipal.value))
const previewCash=computed(()=>(selected.value?.requestedMinor||0)-previewReduction.value)
const stats=computed(()=>({pending:rows.value.filter(r=>r.status==='REQUESTED').length,reduced:rows.value.reduce((s,r)=>s+r.principalReductionMinor,0),returnPending:rows.value.reduce((s,r)=>s+Math.max(0,r.returnPayableMinor-r.returnedMinor),0),returned:rows.value.reduce((s,r)=>s+r.returnedMinor,0)}))
async function load(){const [a,r,f]=await Promise.all([request.get('/after-sales'),request.get('/reviews'),request.get('/credit/overview')]);rows.value=a.data||[];reviews.value=r.data||[];finance.value=f.data}
function open(row){selectedId.value=row.id;reason.value='';detailOpen.value=true}
async function call(path,payload,message){if(busy.value)return;busy.value=true;try{const r=await request.post(path,payload);if(r.code!=='200')return ElMessage.error(r.msg);await load();ElMessage.success(message||'本机记录已更新');return r.data}finally{busy.value=false}}
async function merchantResponse(decision){await call('/after-sales/merchant-response',{id:selected.value.id,decision,reason:reason.value},selected.value.kind==='credit'?'商家意见已保存，财务变化须独立复核':'普通商城售后意见已保存，不代表资金到账')}
async function decide(decision){const row=selected.value;const result=await call('/credit/refund-decision',{refundId:row.id,version:row.version,decision,reason:reason.value,personaId:persona.value,clientKey:'UI-DEC-'+row.id+'-'+row.version},decision==='APPROVE'?'独立复核已通过，请查看本金冲减与应退拆分':'申请未通过，账本未改变');if(result&&decision==='APPROVE')ElMessage.info('冲减本金 ¥'+money(result.principalReductionMinor)+'；待模拟退回 ¥'+money(result.returnPayableMinor))}
async function simulate(row,result){await call('/credit/simulate-refund-result',{refundId:row.id,reference:row.reference,merchantUid:row.merchantUid,amountMinor:row.returnPayableMinor,currency:'CNY',environment:'SIMULATION',personaId:persona.value,providerEventId:'UI-REFUND-'+row.id+'-'+row.attempt+'-'+result,result},result==='CONFIRMED'?'模拟现金退回已记录，不再次增加额度':result==='TIMEOUT'?'结果未知，保持处理中，不能据此重试':'已记录明确演示失败，待独立核查')}
function openReply(review){replyTarget.value=review;replyText.value=reviewPlainText(review.reply);replyOpen.value=true}
async function saveReply(){const r=await call('/reviews/reply',{orderId:replyTarget.value.orderId,text:replyText.value},'回复已保存，顾客可在订单、餐品和店铺评价中查看');if(r)replyOpen.value=false}
watch(persona,value=>sessionStorage.setItem('platformDemoPersona',value))
const sync=e=>{if(e.key==='mall-ui-data-v2')load()};let timer
onMounted(()=>{load();timer=setInterval(load,30000);window.addEventListener('storage',sync)})
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('storage',sync)})
</script>
<template><div class="service-workspace"><header><div><h1>{{merchant?'本店售后与评价':'售后复核与退款记录'}}</h1><p>{{merchant?'处理本店顾客申请，回复评价；商家意见不会直接修改信用应收':'独立审核、模拟现金退回和进度记录，复核前后金额来自同一账本'}}</p></div><el-button :icon="Refresh" @click="load">刷新</el-button></header><el-alert type="warning" :closable="false" title="本机演示，不实际退款" description="信用售后按原规则先冲剩余本金，超出部分形成独立应退；真实支付和退货物流未接入。普通结算仅记录商家处理意见，不改信用账本。"/><div class="service-stats"><div><span>待处理申请</span><strong>{{stats.pending}}</strong></div><div><span>已冲減本金</span><strong>¥{{money(stats.reduced)}}</strong></div><div><span>待模拟退回</span><strong>¥{{money(stats.returnPending)}}</strong></div><div><span>已模拟退回</span><strong>¥{{money(stats.returned)}}</strong></div></div><div v-if="!merchant" class="service-persona"><span>平台合成人格</span><el-select v-model="persona" style="width:280px"><el-option label="模拟结果控制员 · 701" value="701"/><el-option label="独立账务复核人 · 402" value="402"/><el-option label="账务申请人 · 401" value="401"/></el-select><small>申请人与复核人必须为不同 actorId</small></div><el-tabs v-model="tab"><el-tab-pane label="售后处理" name="afterSales"><el-table :data="rows" border><el-table-column prop="id" label="售后号" width="115"/><el-table-column prop="userUid" label="顾客UID" width="145"/><el-table-column v-if="!merchant" prop="merchantUid" label="商家UID" width="125"/><el-table-column prop="title" label="订单餐品" min-width="190"/><el-table-column label="申请金额" width="115"><template #default="{row}">¥{{money(row.requestedMinor)}}</template></el-table-column><el-table-column label="结算类型" width="100"><template #default="{row}">{{row.kind==='credit'?'先吃后付':'普通结算'}}</template></el-table-column><el-table-column label="状态" min-width="160"><template #default="{row}"><el-tag :type="row.status==='SUCCEEDED'?'success':row.status==='REJECTED'||row.status==='FAILED'?'danger':'warning'">{{status(row)}}</el-tag></template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button type="primary" @click="open(row)">{{row.status==='REQUESTED'?'查看并处理':'查看进度'}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="merchant?'店铺评价':'评价记录'" name="reviews"><el-table :data="reviews" border><el-table-column prop="orderId" label="订单餐品号" width="100"/><el-table-column prop="name" label="餐品" min-width="170"/><el-table-column prop="userNickname" label="顾客" width="110"/><el-table-column label="评分" width="140"><template #default="{row}"><el-rate :model-value="row.rate" disabled/></template></el-table-column><el-table-column label="评价" min-width="210"><template #default="{row}"><div v-html="sanitizeHTML(row.comment)"></div></template></el-table-column><el-table-column label="商家回复" min-width="210"><template #default="{row}"><div v-if="row.reply" v-html="sanitizeHTML(row.reply)"></div><span v-else>尚未回复</span></template></el-table-column><el-table-column v-if="merchant" label="操作" width="120"><template #default="{row}"><el-button type="primary" @click="openReply(row)">{{row.reply?'编辑回复':'回复评价'}}</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs>
<el-dialog v-model="detailOpen" title="售后详情与处理" width="780px" :close-on-click-modal="false"><template v-if="selected"><div class="service-detail-head"><img :src="selected.img" :alt="selected.title"/><div><h3>{{selected.title}}</h3><p>{{selected.id}} · {{selected.userUid}} · {{selected.merchantUid}}</p><strong>{{status(selected)}} · 申请 ¥{{money(selected.requestedMinor)}}</strong></div></div><el-descriptions :column="1" border><el-descriptions-item label="申请原因">{{selected.reason}}</el-descriptions-item><el-descriptions-item label="商家意见">{{selected.merchantReason||'尚未反馈'}}</el-descriptions-item><el-descriptions-item label="复核意见">{{selected.decisionReason||'尚未复核'}}</el-descriptions-item><el-descriptions-item v-if="selected.kind==='credit'" label="已执行金额">冲本金 ¥{{money(selected.principalReductionMinor)}}；应退现金 ¥{{money(selected.returnPayableMinor)}}；已模拟退回 ¥{{money(selected.returnedMinor)}}</el-descriptions-item></el-descriptions><template v-if="selected.status==='REQUESTED'"><el-input v-model="reason" type="textarea" :rows="3" maxlength="500" show-word-limit style="margin:18px 0" placeholder="填写商家处理说明或独立复核理由"/><div v-if="merchant" class="service-actions"><el-button type="primary" :disabled="busy||!reason.trim()" @click="merchantResponse('SUPPORT')">{{selected.kind==='credit'?'支持申请，提交处理意见':'同意普通商城售后'}}</el-button><el-button type="danger" plain :disabled="busy||!reason.trim()" @click="merchantResponse('DECLINE')">不认可申请并说明原因</el-button><p v-if="selected.kind==='credit'">这里只记录商家意见，不冲本金或退钱；后续由独立复核人处理。</p></div><div v-else-if="selected.kind==='credit'" class="service-actions"><el-alert type="info" :closable="false" :title="'若通过：按当前剩余应收冲减 ¥'+money(previewReduction)+'，形成模拟待退现金 ¥'+money(previewCash)"/><el-button style="margin-top:14px" type="primary" :disabled="busy||persona!=='402'||!reason.trim()" @click="decide('APPROVE')">402独立审核通过</el-button><el-button type="danger" plain :disabled="busy||persona!=='402'||!reason.trim()" @click="decide('REJECT')">402独立审核拒绝</el-button></div><p v-else>普通结算售后由本店商家反馈；尚未接入资金退款渠道。</p></template><div v-if="!merchant&&selected.kind==='credit'&&selected.returnPayableMinor>0" class="service-actions"><template v-if="selected.status==='PROCESSING'"><el-alert :closable="false" type="info" :title="selected.channelResult==='UNKNOWN'?'模拟渠道结果未知，保持处理中，不能据此重试':'等待701模拟退款结果'"/><el-button style="margin-top:12px" type="success" :disabled="busy||persona!=='701'" @click="simulate(selected,'CONFIRMED')">完成模拟现金退回</el-button><el-button :disabled="busy||persona!=='701'" @click="simulate(selected,'TIMEOUT')">演示结果未知</el-button><el-button type="danger" plain :disabled="busy||persona!=='701'" @click="simulate(selected,'FAILED')">演示明确失败</el-button></template><template v-else-if="selected.status==='FAILED'"><el-button type="warning" :disabled="busy||persona!=='402'" @click="call('/credit/refund-retry',{refundId:selected.id,version:selected.version,personaId:persona,clientKey:'UI-RETRY-'+selected.id+'-'+selected.version,reason:'独立核对已明确失败后重试'},'已重试待退部分，不再冲减本金或释放额度')">402核查后重试</el-button><el-button :disabled="busy||persona!=='701'" @click="simulate(selected,'CONFIRMED')">注入迟到成功（演示）</el-button></template><el-button v-else-if="selected.status==='SUCCEEDED'" :disabled="busy||persona!=='701'" @click="simulate(selected,'CONFIRMED')">重放同一成功结果验证幂等</el-button></div><h3>实际处理记录</h3><el-timeline><el-timeline-item v-for="(event,index) in selected.history" :key="index" :timestamp="date(event.at)"><strong>{{event.type}}</strong> · actor {{event.actorId}}<p>{{event.note}}</p></el-timeline-item></el-timeline></template></el-dialog>
<el-dialog v-model="replyOpen" title="回复顾客评价" width="560px" :close-on-click-modal="false"><template v-if="replyTarget"><p>{{replyTarget.name}} · {{replyTarget.rate}}星</p><div class="original-review" v-html="sanitizeHTML(replyTarget.comment)"></div><el-input v-model="replyText" type="textarea" :rows="5" placeholder="填写商家回复（1至500字）" maxlength="500" show-word-limit/></template><template #footer><el-button @click="replyOpen=false">取消</el-button><el-button type="primary" :disabled="busy||!replyText.trim()" @click="saveReply">保存回复</el-button></template></el-dialog>
</div></template>
<style scoped>.service-workspace{padding:24px;min-width:700px;background:#f6f8fb;min-height:100%}.service-workspace>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;gap:20px}.service-workspace h1{font-size:24px;margin:0 0 8px;color:#293e58}.service-workspace header p{font-size:13px;color:#8793a4;margin:0}.service-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:20px 0}.service-stats>div{background:white;border:1px solid #e3e9f0;padding:22px;border-radius:9px}.service-stats span{font-size:13px;color:#8190a3}.service-stats strong{display:block;margin-top:12px;font-size:26px;color:#304764}.service-persona{display:flex;align-items:center;gap:16px;padding:14px;background:white;border-radius:8px;margin-bottom:18px;font-size:13px}.service-persona small{font-size:11px;color:#97a2b2}.service-detail-head{display:flex;gap:16px;align-items:center;margin-bottom:20px}.service-detail-head img{width:85px;height:85px;border-radius:7px;object-fit:cover}.service-detail-head h3{margin:0 0 8px}.service-detail-head p{font-size:12px;color:#8b98a8}.service-actions{margin:20px 0;padding:16px;background:#f8fafc;border:1px solid #e7ecf2;border-radius:8px}.service-actions p{font-size:12px;color:#9aa5b2;line-height:1.8}.original-review{padding:14px;background:#f7f7f7;margin:14px 0;border-radius:6px}.service-workspace :deep(.el-table){font-size:13px}@media(max-width:1000px){.service-stats{grid-template-columns:repeat(2,1fr)}}</style>
